      zenPage.addChild(group);

      var lbl = this.createComponent('label'); 
      group.addChild(lbl); 
      lbl.setProperty('value','Please Wait, Getting items for: ' + val)
		zenPage.refreshContents(true); 
    	group.show('Verify', 'dynamic');
    	*/
     	zenPage.getComponentById('lblAccess').setProperty('hidden', false);

		  timerVar = setInterval(function(){ zenPage.VerifyTimer()}, 1000);
		  var time1 = new Date();
		  time1ms= time1.getTime(time1);
  		  zenPage.GetSrcCtrlItems();


	} catch(e){
        alert('refreshSrcCtrlInfo: Catch error:' +e.message);
        zenSynchronousMode = true;
        clearInterval(this);
    }

   try
	    {
		    var time2 = new Date();
		    time2ms= time2.getTime(time2);
		    if(time2ms - time1ms > 120000)
		    {
			    clearInterval(timerVar); 

   				zenSynchronousMode = true;
   				zenPage.getComponentById('lblAccess').setValue('TimeOut');
		    }
		    var labVal = zenPage.getComponentById('lblAccess').getValue();
		    // zenPage.WriteLable(labVal + ", " + (time2ms - time1ms));
		    if( labVal.substr(0, 10)  != 'Retrieving')
  			{
	  			clearInterval(timerVar); 
	  			if (zenPage.modalStack != null && zenPage.modalStack.length>0)
	  			{
	  				zenPage.endModal();		
	  			}		
   				zenSynchronousMode = true;
   				 // refresh data in contact table
   				if( zenPage.getComponentById('lblAccess').getValue().substr(0, 4) == 'Done')
  				{ 
          			var table = zenPage.getComponentById('srcCtrlTable');
          			table.executeQuery();   			  				 
  				}
  			}
  			else
  			{
	  			var val = zenPage.getComponentById('lblAccess').getValue();
	  			if (val.length > 21)
	  			{
		  			zenPage.getComponentById('lblAccess').setValue('Retrieving.');
	  			}
	  			else
	  			{
	  			  zenPage.getComponentById('lblAccess').setValue(zenPage.getComponentById('lblAccess').getValue() + ".");
	  			}
  			}


} catch(err)
	    {
		    zenPage.getComponentById('lblAccess').setValue('Exception in VerifyTimer: ' + err.message);
		    clearInterval(timerVar);
		    zenSynchronousMode = true;
	    }

	try
	{
