set retRows = 1
set retStat = ""
try
{
	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Start GetSrcCtrlItems")
	set vCls = ##class(IHC.ITF.SrcCtrlPkg.ItfSrcCtrlUtil).%New()
  SET stat = vCls.GetItems( $get(%session.Data("NmSp")), $get(%session.Data("UsNm")), $get(%session.Data("PsWd")), .retRows)
  if ($$$ISOK(stat))
  {
	  	set retStat = "Done, number of items: " _ retRows 
  		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("GetSrcCtrlItems: status OK , rows: " _ retRows)
  }
  else
  {
	  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("GetSrcCtrlItems: status fail: " _ stat)
  }
} catch err
{
	set retStat = "Error in GetItems"
	set errStr = err.Data _ " " _ err.Name
	&js<alert('Error in Setup, check debug file ');>
	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Error in GetSrcCtrlItems: " _ errStr)
}
Do ..%SetValueById("lblAccess", retStat)
set val = ..%GetValueById("lblAccess")

Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("End GetSrcCtrlItems: " _ val)
Quit

set rows = 1

try
{
Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Start  GetSVNItems")	
  SET rows = ##class(IHC.ITF.SrcCtrlPkg.ItfSrcCtrlUtil).UpdateAllSvnFiles( $get(%session.Data("NmSp")), $get(%session.Data("UsNm")), $get(%session.Data("PsWd")))

} catch err
{
	set errStr = err.Data _ " " _ err.Name
	&js<alert('Error in Setup, check debug file ');>
	set rows = 0
}
Quit rows

 set val = %query(pName) 	
 if ( $F(val, "LOOKUP") > 0)
 { 
	Write "<FONT COLOR=""BLUE"">" _ val _ "</FONT>"
 } 
 Elseif ( $F(val, "SYSDEF") > 0)
 { 
	Write "<FONT COLOR=""GREEN"">" _ val _ "</FONT>"
 } 
 else 
 { 
	Write val 
 } 

 Quit $$$OK


 If %query(pName) 
 { 


   set val = $GET(%query("ClassModifiedTime"))

   set srcVal = %query(pName)


   if (srcVal '= "")
   { 
      Set fileTime=$ZDATETIMEH(srcVal, 3, 1)

   }



   if (val = "")
   {
	   set srcVal = "<B> " _ srcVal _ " </B>"
	   Write srcVal
	   Quit $$$OK
   }
   else
   {
     Set intTime=$ZDATETIMEH(val, 3, 1)
   }



  // if date is greater OR date is same and time is greater
  if ( 
       ($p(intTime, ",", 1) > $p(fileTime, ",", 1)) || 
       (
         ($p(intTime, ",", 1) = $p(fileTime, ",", 1)) && ($p(intTime, ",", 2) > $p(fileTime, ",", 2))
       )
    )
   {	   
	   set srcVal = "<B><I><FONT COLOR=""RED"">" _ srcVal _ "</FONT></I></B>"
   }
   elseif(srcVal = "")
   {

    set srcVal = "<B><I> <FONT COLOR=""RED""> Not in SubVersion </FONT> </I></B>"

   }

   Write srcVal

 }
 else // %query
 {
	Write "<B><I> Not in SubVersion </I></B>"
 }
 Quit $$$OK
